"""Explicit source transcriptions of FITRR workbook conceptual models."""
from pathlib import Path
import json,sys
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'tools'))
from extract_workbooks import write
SID='src-000322';JOB='job-000001';OUT=ROOT/'work/fitrr-workbook-models'
results=json.loads((ROOT/'work/workbook-results.json').read_text('utf-8'));DIAGS={d['figure_id']:d for r in results if r['source_id']==SID for d in r['diagrams']}
def e(a,b,label='',kind='--'):return dict(a=a,b=b,label=label,kind=kind)
def g(a,b):return e(a,b,kind='--|>')
def ns(names,package='not printed in figure'):return [dict(id=n,name=n,package=package,stereotype='BusinessComponent') for n in names.split()]
models=[]
names='Role RolePlayer AssetPartyRole SystemPartyRole SettlementPartyRole RegulatoryReportingRole TradePartyRole AccountPartyRole SecuritiesPartyRole IssuerRole SubmittingPartyRole SellerRole BuyerRole AccountOwnerRole InvestmentAccountPartyRole RegistrarRole Investor'
nodes=ns(names,'DICO_BusinessComponents')
for n in nodes:
 if n['name'] in ['SecuritiesPartyRole','RegistrarRole']:n['package']='not printed in figure'
edges=[e('Role','RolePlayer','+ Player')]+[g(n,'Role') for n in ['AssetPartyRole','SystemPartyRole','SettlementPartyRole','RegulatoryReportingRole','TradePartyRole','AccountPartyRole']]+[g('SecuritiesPartyRole','AssetPartyRole'),g('IssuerRole','AssetPartyRole'),g('RegistrarRole','SecuritiesPartyRole'),g('SubmittingPartyRole','SystemPartyRole'),g('SellerRole','TradePartyRole'),g('BuyerRole','TradePartyRole'),g('AccountOwnerRole','AccountPartyRole'),g('InvestmentAccountPartyRole','AccountPartyRole'),g('Investor','InvestmentAccountPartyRole')]
models.append(dict(id='fig-0002',title='FITRR role players and contextual business roles',nodes=nodes,edges=edges,meaning='Role is associated with RolePlayer by Player; roles and the entities playing them remain distinct. Role generalizes asset, system, settlement, regulatory-reporting, trade and account roles. SecuritiesPartyRole and IssuerRole specialize AssetPartyRole; RegistrarRole further specializes SecuritiesPartyRole. SubmittingPartyRole specializes SystemPartyRole, buyer/seller specialize trade role, account owner and investment-account party specialize account role, and investor specializes investment-account party role. No message direction or permanent institution identity follows from this hierarchy.'))
names='SecuritiesIdentification DateTimePeriod Status TradingMarket Issuance PlaceOfSettlement Market PartyIdentificationInformation Party OrganisationIdentification Organisation Person FinancialInstitution NonFinancialInstitution PersonIdentification Security SecuritiesQuantity Debt MasterAgreement Obligation TradeIdentification Trade System ClearingSystem TradePartyRole SecuritiesTradePartyRole SecuritiesTrade Asset AssetClassification Scheme Derivative Option Swaps SecuritiesPricing Index AssetHolding Interest InterestCalculation Spread Curve'
nodes=ns(names)
dico='PartyIdentificationInformation Party OrganisationIdentification Organisation SecuritiesQuantity MasterAgreement Obligation TradeIdentification Trade System ClearingSystem TradePartyRole SecuritiesTradePartyRole SecuritiesTrade Asset Derivative SecuritiesPricing Index'.split()
for n in nodes:
 if n['name'] in dico:n['package']='DICO_BusinessComponents'
 if n['name'] in ['Security','AssetClassification','Option']:n['package']='Securities'
 if n['name']=='Scheme':n['package']='DICO_BusinessComponentsDataTypes'
edges=[e('SecuritiesIdentification','SecuritiesIdentification','+ PrimeIdentification / + RelatedOtherIdentification'),e('SecuritiesIdentification','TradingMarket','+ ListedSecurityTradingIdentification / + ApplicableTradingMarket'),e('SecuritiesIdentification','Security','+ Identification / + IdentifiedSecurity'),e('TradingMarket','Issuance','- IssuePlace'),e('TradingMarket','PlaceOfSettlement','- SettlementMarket / - RelatedPlaceOfSettlement'),e('DateTimePeriod','Status','+ ValidityTime'),e('DateTimePeriod','Issuance','+ SubscriptionPeriod'),e('DateTimePeriod','System','- VersionValidityPeriod'),e('Market','Trade'),e('Market','PartyIdentificationInformation','- IdentifiedMarket / - Identification'),e('PartyIdentificationInformation','Party','+ Identification / + IdentifiedParty'),g('OrganisationIdentification','PartyIdentificationInformation'),e('OrganisationIdentification','Organisation'),g('Organisation','Party'),g('Person','Party'),g('FinancialInstitution','Organisation'),g('NonFinancialInstitution','Organisation'),e('Person','PersonIdentification'),e('Party','Security','- CloseLink / - CloseLinkSecurity'),e('Issuance','SecuritiesQuantity','+ RelatedIssuance / + Minimum'),e('Issuance','SecuritiesQuantity','- IssueNominalAmount'),e('MasterAgreement','Trade','+ GoverningDocument / + GovernedTrades'),e('Obligation','Trade'),e('TradeIdentification','Trade'),e('System','Trade'),g('ClearingSystem','System'),e('Trade','Asset'),e('Trade','TradePartyRole'),g('SecuritiesTrade','Trade'),g('SecuritiesTradePartyRole','TradePartyRole'),e('SecuritiesTradePartyRole','SecuritiesTrade','+ PartyRole'),e('SecuritiesQuantity','SecuritiesTrade','+ TradeQuantity / + Trade'),e('SecuritiesQuantity','Security','+ SecurityIdentification'),g('Debt','Security'),e('Debt','SecuritiesQuantity','+ MinimumDenominationDebt / - MinimumDenomination'),e('Debt','SecuritiesQuantity','+ MinimumIncrementDebt / - MinimumIncrement'),e('Debt','InterestCalculation','+ DebtInstrument / + NextInterest'),e('InterestCalculation','Interest'),e('Interest','AssetHolding','+ RelatedAssetHolding'),e('AssetHolding','Asset','+ AssetValue'),e('Asset','AssetClassification'),e('AssetClassification','Scheme','- AssetClassScheme'),g('Derivative','Asset'),e('Derivative','Asset','+ UnderlyingAsset'),g('Option','Derivative'),g('Swaps','Derivative'),e('Derivative','SecuritiesPricing','+ RelatedFuture / + Tick'),e('SecuritiesPricing','Index'),e('Index','Spread'),e('Spread','Security','+ BenchmarkSecurity'),e('Spread','InterestCalculation','- RelatedInterest'),e('Spread','Curve','+ BenchmarkCurve')]
models.append(dict(id='fig-0003',title='FITRR regulatory data identification and financial-asset context',nodes=nodes,edges=edges,meaning='The complete model connects securities identification, trading and settlement places, issuance and validity periods, party and organisation identities, trade identifiers and parties, governing agreement, system and clearing-system context, securities quantities, debt and interest calculations, asset classification, derivatives and price/benchmark relationships. Security identification has a self-association for prime and related identification. Issuance has two distinct quantity associations; debt also has separate denomination and increment associations. Derivative–Asset is displayed with a hollow-triangle generalization and UnderlyingAsset association sharing the same vertical route. FullBusinessModel!A1545:F1546 independently establishes both relationships, so the reconstruction separates the overlapping route into two lines rather than treating UnderlyingAsset as an inheritance label. Security–Asset inheritance exists in the workbook definition but is not drawn in this view and is not added to the source reconstruction. The figure is a conceptual reference model, not a database or business-message flow.',limitations=[]))
for m in models:
 code='classDiagram\ndirection TB\n'
 for n in m['nodes']:code+='class '+n['id']+' {\n<<'+n['stereotype']+'>>\n}\n'
 for r in m['edges']:code+=r['a']+' '+r['kind']+' '+r['b']+(' : '+r['label'] if r['label'] else '')+'\n'
 m.update(source_id=SID,source=DIAGS[m['id']],mermaid=code,render_prefix=SID+'-'+m['id'],review_status='needs-review',package_note='Printed package labels are preserved in the entity register. Nodes without a printed package remain explicitly unqualified in that register; no enclosing package boundaries are invented.');m.setdefault('limitations',[])
 write(ROOT,OUT/(m['render_prefix']+'.mmd'),code,JOB)
write(ROOT,OUT/'models.json',json.dumps(models,ensure_ascii=False,indent=2),JOB)
print(json.dumps([{'id':m['id'],'nodes':len(m['nodes']),'edges':len(m['edges'])} for m in models]))
